<style> .form-card { background:#fff; border-radius:8px; padding:24px; box-shadow:0 1px 6px rgba(0,0,0,0.06); max-width:500px; } .form-group { margin-bottom:20px; } .form-group label { display:block; font-size:14px; font-weight:500; margin-bottom:6px; color:#555; } .form-group input, .form-group select { width:100%; padding:10px 14px; border:1px solid #d0d0d0; border-radius:6px; font-size:15px; } .form-group input:focus, .form-group select:focus { outline:none; border-color:#1a73e8; box-shadow:0 0 0 3px rgba(26,115,232,0.1); } .form-group .error { color:#c62828; font-size:13px; margin-top:4px; } .btn { padding:10px 24px; border:none; border-radius:6px; font-size:15px; font-weight:600; cursor:pointer; } .btn-primary { background:#1a73e8; color:#fff; } .btn-primary:hover { background:#1557b0; } .btn-secondary { background:#e0e0e0; color:#333; margin-left:8px; text-decoration:none; display:inline-block; padding:10px 24px; border-radius:6px; font-size:15px; } </style> <div class="form-card"> <h2 style="margin-bottom:20px;"><?= isset($data['id']) ? 'Edit' : 'Tambah' ?> Kecamatan</h2> <form method="POST" action="/wilayah/kecamatan/<?= isset($data['id']) ? 'update/'.$data['id'] : 'store' ?>"> <?= \App\Core\Security::csrfField() ?> <div class="form-group"> <label for="kabupaten_id">Kabupaten</label> <select id="kabupaten_id" name="kabupaten_id" required> <option value="">-- Pilih Kabupaten --</option> <?php foreach ($kabupaten as $k): ?> <option value="<?= (int) $k['id'] ?>" <?= ((int)($data['kabupaten_id'] ?? 0) === (int)$k['id']) ? 'selected' : '' ?>> <?= \App\Core\Security::e($k['nama_kabupaten']) ?> </option> <?php endforeach; ?> </select> <?php if (!empty($errors['kabupaten_id'])): ?><div class="error"><?= \App\Core\Security::e($errors['kabupaten_id']) ?></div><?php endif; ?> </div> <div class="form-group"> <label for="kode">Kode Kecamatan</label> <input type="text" id="kode" name="kode" maxlength="10" required value="<?= \App\Core\Security::e($data['kode'] ?? '') ?>"> <?php if (!empty($errors['kode'])): ?><div class="error"><?= \App\Core\Security::e($errors['kode']) ?></div><?php endif; ?> </div> <div class="form-group"> <label for="nama_kecamatan">Nama Kecamatan</label> <input type="text" id="nama_kecamatan" name="nama_kecamatan" maxlength="100" required value="<?= \App\Core\Security::e($data['nama_kecamatan'] ?? '') ?>"> <?php if (!empty($errors['nama_kecamatan'])): ?><div class="error"><?= \App\Core\Security::e($errors['nama_kecamatan']) ?></div><?php endif; ?> </div> <div> <button type="submit" class="btn btn-primary">Simpan</button> <a href="/wilayah" class="btn-secondary">Batal</a> </div> </form> </div> 